package dididid;

public class Board {

		int boardNum;
		String boardTitle;
		String boardContent;
		String boardWriter;
		String boardDate;
		int boardHit;
		
		
		public Board() {
			super();
			// TODO Auto-generated constructor stub
		}
		public Board(int boardNum, String boardTitle, String boardContent, String boardWriter, String boardDate,
				int boardHit) {
			super();
			this.boardNum = boardNum;
			this.boardTitle = boardTitle;
			this.boardContent = boardContent;
			this.boardWriter = boardWriter;
			this.boardDate = boardDate;
			this.boardHit = boardHit;
		}
		
		
	
		
		
		
		
		
}
